const crypto = require('crypto');

const item = $input.item.json;
const headers = item.headers || {};
const body = item.body || item;
const secret = $env.N8N_WEBHOOK_SECRET || '';

const signature = headers['x-aurelle-signature'] || headers['X-Aurelle-Signature'];
const timestamp = headers['x-aurelle-timestamp'] || headers['X-Aurelle-Timestamp'];
const eventId = headers['x-aurelle-event-id'] || headers['X-Aurelle-Event-ID'];

// 1. Header checks
if (!signature || !timestamp || !eventId) {
  return [{ json: { isValid: false, reason: 'Missing cryptographic signature headers' } }];
}

// 2. Reject expired requests (300 seconds tolerance)
const occurredMs = new Date(timestamp).getTime();
if (isNaN(occurredMs) || Math.abs(Date.now() - occurredMs) > 300000) {
  return [{ json: { isValid: false, reason: 'Timestamp drift exceeds 300 seconds' } }];
}

// 3. HMAC-SHA256 verification
let signatureValid = false;
if (secret) {
  const payloadBytes = Buffer.from(JSON.stringify(body));
  const expectedHmac = crypto.createHmac('sha256', secret).update(payloadBytes).digest('hex');
  signatureValid = (signature.toLowerCase() === expectedHmac.toLowerCase());
} else {
  signatureValid = Boolean($env.NODE_ENV !== 'production');
}

const payload = body.payload || {};
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const hasValidEmail = typeof payload.client_email === 'string' && emailRegex.test(payload.client_email.trim());

return [{
  json: {
    isValid: signatureValid && hasValidEmail,
    reason: !signatureValid ? 'Invalid signature' : !hasValidEmail ? 'Invalid client email address' : 'OK',
    event_id: body.event_id || eventId,
    enquiry_id: payload.enquiry_id,
    reference_code: payload.reference_code || `AUR-${String(payload.enquiry_id || '').slice(-6).toUpperCase()}`,
    client_name: (payload.client_name || '').trim(),
    client_email: (payload.client_email || '').trim().toLowerCase(),
    idempotency_key: `cust_ack_${payload.enquiry_id}`,
  }
}];
